    static var one_body: String { String(localized: "SourceReader.1.body", defaultValue: "Glycogen stores glucose in a branched particle of up to about 55,000 glucose molecules. The enzyme releases glucose only from the outer layer, so the whole reserve cannot be used at once. A chemistry review, not a study of fasting people.") }
    static var two_title: String { String(localized: "SourceReader.2.title", defaultValue: "Does fasting every other day work better?") }
    static var two_body: String { String(localized: "SourceReader.2.body", defaultValue: "For one year, 100 adults with obesity were compared. One group fasted every other day: about 25% of their usual calories on fasting days and slightly more than usual on the others. The second ate 75% of usual calories every day. Average weight fell 6.0% and 5.3% - no meaningful difference. More people left the alternate-day group (38% vs 29%), and its \"bad\" cholesterol was higher; the study does not explain why.") }
    static var three_title: String { String(localized: "SourceReader.3.title", defaultValue: "Autophagy: understanding a mechanism") }
    static var three_body: String { String(localized: "SourceReader.3.body", defaultValue: "In mice, fasting raises the hormone FGF21, which starts cellular cleanup; the liver then digests its own fat. Giving obese mice FGF21 cleared fatty liver. No fasting people were studied.") }
    static var four_title: String { String(localized: "SourceReader.4.title", defaultValue: "Fasting and metabolic health") }
    static var four_body: String { String(localized: "SourceReader.4.body", defaultValue: "A review with no measurements of its own. It reports that fasting schedules, including a 6-hour eating window, are associated with lower weight, better cholesterol and triglycerides, and lower blood pressure, and that longer trials are still needed.") }
